import app from './__APP_IMPORT_PATH__';

function arrayBufferToBase64(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
}

function base64UrlEncodeString(str) {
  return arrayBufferToBase64(new TextEncoder().encode(str).buffer)
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

const DEHYDRATE_FILE_PREFIX = 'whippy:dehydrate-file:';
const DEHYDRATE_INPUT_DATA_MAX_BYTES = 12_288;
const DEFAULT_CACHE_EXPIRATION_SECONDS = 300;
const MAX_CACHE_EXPIRATION_SECONDS = 86_400;

function workflowApiOrigin(bundle) {
  if (bundle?.target_url) {
    try {
      return new URL(bundle.target_url).origin;
    } catch {
      // fall through
    }
  }
  if (bundle?.meta?.workflow_host) {
    return String(bundle.meta.workflow_host).replace(/\/$/, '');
  }
  throw new Error('Cannot determine workflow API host for stashFile (missing target_url).');
}

async function resolveStashFilePayload(input, options = {}) {
  let value = input;
  if (value && typeof value.then === 'function') {
    value = await value;
  }

  if (value instanceof ReadableStream) {
    value = await new Response(value).arrayBuffer();
  }

  if (value instanceof ArrayBuffer || value instanceof Uint8Array) {
    const buffer =
      value instanceof ArrayBuffer
        ? value
        : value.buffer.slice(value.byteOffset, value.byteOffset + value.byteLength);
    return {
      base64: arrayBufferToBase64(buffer),
      filename: options.filename || 'file.bin',
      content_type:
        options.content_type ||
        options.contentType ||
        guessContentType(options.filename),
    };
  }

  if (typeof Blob !== 'undefined' && value instanceof Blob) {
    const buffer = await value.arrayBuffer();
    return {
      base64: arrayBufferToBase64(buffer),
      filename: options.filename || value.name || 'file.bin',
      content_type: value.type || options.content_type || options.contentType,
    };
  }

  if (value && typeof value === 'object' && value.data instanceof ArrayBuffer) {
    const buffer = value.data;
    const contentType =
      value.contentType ||
      value.content_type ||
      value.headers?.['content-type'] ||
      value.headers?.['Content-Type'] ||
      options.content_type ||
      options.contentType;
    return {
      base64: arrayBufferToBase64(buffer),
      filename: options.filename || 'file.bin',
      content_type: contentType || guessContentType(options.filename),
    };
  }

  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (/^https?:\/\//i.test(trimmed)) {
      return {
        url: trimmed,
        filename: options.filename,
        content_type: options.content_type || options.contentType,
      };
    }
    return {
      base64: trimmed,
      filename: options.filename || 'file.bin',
      content_type: options.content_type || options.contentType,
    };
  }

  if (value && typeof value === 'object' && value.url) {
    return {
      url: String(value.url),
      filename: options.filename || value.filename,
      content_type: options.content_type || value.content_type || value.contentType,
    };
  }

  throw new Error(
    'Invalid stashFile input. Provide a URL string, buffer, stream, raw w.request response, or promise thereof.',
  );
}

function buildDehydrateFilePointer(bundle, hydratorKey, inputData, options = {}) {
  const meta = bundle?.meta || {};
  const appVersionId = meta.app_version_id;
  if (!appVersionId) {
    throw new Error('bundle.meta.app_version_id is required for dehydrateFile');
  }
  if (!hydratorKey || typeof hydratorKey !== 'string') {
    throw new Error('dehydrateFile requires a hydrator key string');
  }

  const cacheExpiration =
    options.cacheExpiration ?? DEFAULT_CACHE_EXPIRATION_SECONDS;
  if (
    typeof cacheExpiration !== 'number' ||
    !Number.isFinite(cacheExpiration) ||
    cacheExpiration < 1 ||
    cacheExpiration > MAX_CACHE_EXPIRATION_SECONDS
  ) {
    throw new Error(
      `cacheExpiration must be between 1 and ${MAX_CACHE_EXPIRATION_SECONDS} seconds`,
    );
  }

  const payload = {
    hydrator: hydratorKey,
    inputData: inputData ?? {},
    app_version_id: appVersionId,
    cacheExpiration,
  };
  const json = JSON.stringify(payload);
  const size = new TextEncoder().encode(json).byteLength;
  if (size > DEHYDRATE_INPUT_DATA_MAX_BYTES) {
    throw new Error('Dehydrated file inputData exceeds 12 KB limit');
  }

  return `${DEHYDRATE_FILE_PREFIX}${base64UrlEncodeString(json)}`;
}

function base64ToUint8Array(base64) {
  const normalized = base64.replace(/\s/g, '');
  const binary = atob(normalized);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

function guessContentType(filename, explicit) {
  if (explicit) return explicit;
  const lower = (filename || '').toLowerCase();
  if (lower.endsWith('.pdf')) return 'application/pdf';
  if (lower.endsWith('.png')) return 'image/png';
  if (lower.endsWith('.jpg') || lower.endsWith('.jpeg')) return 'image/jpeg';
  if (lower.endsWith('.txt')) return 'text/plain';
  if (lower.endsWith('.doc')) return 'application/msword';
  if (lower.endsWith('.docx')) {
    return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
  }
  return 'application/octet-stream';
}

async function resolveFileBlob(fileInput, part) {
  const filename =
    part.filename ||
    (fileInput && typeof fileInput === 'object' && fileInput.filename) ||
    'upload.bin';
  const contentType =
    part.contentType ||
    part.content_type ||
    (fileInput &&
      typeof fileInput === 'object' &&
      (fileInput.content_type || fileInput.contentType)) ||
    guessContentType(filename);

  if (fileInput == null || fileInput === '') {
    throw new Error('File field is required.');
  }

  if (typeof fileInput === 'string') {
    const trimmed = fileInput.trim();
    if (/^https?:\/\//i.test(trimmed)) {
      const fileRes = await fetch(trimmed);
      if (!fileRes.ok) {
        throw new Error(`Failed to fetch file URL: HTTP ${fileRes.status}`);
      }
      const data = await fileRes.arrayBuffer();
      const type = fileRes.headers.get('content-type') || contentType;
      return new Blob([data], { type });
    }
    const bytes = base64ToUint8Array(trimmed);
    return new Blob([bytes], { type: contentType });
  }

  if (typeof fileInput === 'object') {
    const url = fileInput.url;
    if (url) {
      const fileRes = await fetch(String(url));
      if (!fileRes.ok) {
        throw new Error(`Failed to fetch file URL: HTTP ${fileRes.status}`);
      }
      const data = await fileRes.arrayBuffer();
      const type = fileRes.headers.get('content-type') || contentType;
      return new Blob([data], { type });
    }
    const b64 = fileInput.base64 ?? fileInput.data;
    if (b64) {
      const bytes = base64ToUint8Array(String(b64));
      return new Blob([bytes], { type: contentType });
    }
  }

  throw new Error(
    'Invalid file input. Use a URL string, base64 string, or { url } / { base64, filename }.',
  );
}

async function buildMultipartFormData(parts) {
  if (!Array.isArray(parts) || parts.length === 0) {
    throw new Error('multipart must be a non-empty array of parts.');
  }
  const form = new FormData();
  for (const part of parts) {
    const name = part.name;
    if (!name) throw new Error('Each multipart part requires a name.');
    const partType = (part.type || 'text').toLowerCase();
    if (partType === 'file') {
      const fileInput = part.value ?? part.file;
      const blob = await resolveFileBlob(fileInput, part);
      const filename =
        part.filename ||
        (fileInput && typeof fileInput === 'object' && fileInput.filename) ||
        (typeof blob.name === 'string' && blob.name) ||
        'upload.bin';
      form.append(name, blob, filename);
    } else {
      const value = part.value;
      if (value !== undefined && value !== null && String(value) !== '') {
        form.append(name, String(value));
      }
    }
  }
  return form;
}

function createW(bundle) {
  return {
    request: async (options) => {
      const url = options.url;
      const method = options.method || 'GET';
      const headers = { ...(options.headers || {}) };
      const params = options.params;

      let body = undefined;
      let requestHeaders = { ...headers };

      if (options.multipart != null) {
        body = await buildMultipartFormData(options.multipart);
        delete requestHeaders['Content-Type'];
        delete requestHeaders['content-type'];
      } else if (options.body !== undefined) {
        body =
          typeof options.body === 'string' ? options.body : JSON.stringify(options.body);
        if (!requestHeaders['Content-Type'] && !requestHeaders['content-type']) {
          requestHeaders['Content-Type'] = 'application/json';
        }
      }

      let requestUrl = url;
      if (params) {
        const urlObj = new URL(url);
        Object.entries(params).forEach(([key, value]) => {
          urlObj.searchParams.append(key, String(value));
        });
        requestUrl = urlObj.toString();
      }

      // `redirect` defaults to 'follow'. Pass 'manual' to stop on the first
      // 3xx so callers can read the Location header (e.g. Bullhorn OAuth code).
      const response = await fetch(requestUrl, {
        method,
        headers: requestHeaders,
        body,
        redirect: options.redirect || 'follow',
      });

      const responseHeaders = {};
      response.headers.forEach((value, key) => {
        responseHeaders[key] = value;
      });

      if (options.raw) {
        const data = await response.arrayBuffer();
        return {
          status: response.status,
          headers: responseHeaders,
          data,
          contentType: response.headers.get('content-type'),
        };
      }

      const bodyText = await response.text();
      let data;
      const contentType = response.headers.get('content-type') || '';
      const isJsonContentType =
        contentType.toLowerCase().includes('application/json') ||
        contentType.toLowerCase().includes('+json');
      if (isJsonContentType && bodyText) {
        try {
          data = JSON.parse(bodyText);
        } catch {
          data = bodyText;
        }
      } else {
        data = bodyText;
      }

      return {
        status: response.status,
        headers: responseHeaders,
        data,
      };
    },

    console: {
      log: (...args) => console.log('[user]', ...args),
      warn: (...args) => console.warn('[user]', ...args),
      error: (...args) => console.error('[user]', ...args),
    },

    errors: {
      Error: class extends Error {},
      ExpiredAuthError: class extends Error {
        name = 'ExpiredAuthError';
      },
      RefreshAuthError: class extends Error {
        name = 'RefreshAuthError';
      },
      HaltedError: class extends Error {
        name = 'HaltedError';
      },
      ThrottledError: class extends Error {
        name = 'ThrottledError';
      },
    },

    JSON: {
      parse: (str) => {
        try {
          return JSON.parse(str);
        } catch {
          return null;
        }
      },
      stringify: JSON.stringify,
    },

    stashFile: async (input, options = {}) => {
      const meta = bundle?.meta || {};
      if (!meta.execution_token) {
        throw new Error('bundle.meta.execution_token is required for stashFile');
      }

      const file = await resolveStashFilePayload(input, options);
      const origin = workflowApiOrigin(bundle);
      const response = await fetch(`${origin}/api/v1/workflow_files/stash`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ meta, file }),
      });

      const bodyText = await response.text();
      let body;
      try {
        body = JSON.parse(bodyText);
      } catch {
        body = bodyText;
      }

      if (!response.ok) {
        const message =
          body?.errors?.detail ||
          body?.error ||
          `stashFile failed: HTTP ${response.status}`;
        throw new Error(message);
      }

      const url = body?.data?.url;
      if (!url) {
        throw new Error('stashFile response missing data.url');
      }
      return url;
    },

    dehydrateFile: (hydratorKey, inputData, options = {}) =>
      buildDehydrateFilePointer(bundle, hydratorKey, inputData, options),

    dehydrate: (hydratorKey, inputData, options = {}) =>
      buildDehydrateFilePointer(bundle, hydratorKey, inputData, options),
  };
}

function normalizeWorkerError(error) {
  const err =
    error instanceof Error
      ? error
      : new Error(
          typeof error === 'string' && error.trim() !== ''
            ? error
            : 'Worker execution failed',
        );
  console.error('Worker execution error:', err.message);
  if (err.stack) {
    console.error(err.stack);
  }
  const body = {
    error: err.message || 'Worker execution failed',
  };
  if (err.name && err.name !== 'Error') {
    body.error_type = err.name;
  }
  if (err.stack) {
    body.stack = err.stack;
  }
  return body;
}

function resolveFunction(functionPath) {
  const parts = functionPath.split('.');
  let current = app;

  for (const part of parts) {
    if (current === null || current === undefined) {
      throw new Error(`Function path not found: ${functionPath}`);
    }
    current = current[part];
  }

  if (typeof current !== 'function') {
    throw new Error(`Path does not resolve to a function: ${functionPath}`);
  }

  return current;
}

export default {
  async fetch(request) {
    try {
      if (request.method !== 'POST') {
        return new Response(JSON.stringify({ error: 'Method not allowed' }), {
          status: 405,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      const { function: functionPath, bundle } = await request.json();

      if (!functionPath || !bundle) {
        return new Response(JSON.stringify({ error: 'Missing function or bundle' }), {
          status: 400,
          headers: { 'Content-Type': 'application/json' },
        });
      }

      const w = createW(bundle);
      const fn = resolveFunction(functionPath);
      const result = await fn(w, bundle);

      return new Response(JSON.stringify({ data: result }), {
        headers: { 'Content-Type': 'application/json' },
      });
    } catch (error) {
      return new Response(JSON.stringify(normalizeWorkerError(error)), {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      });
    }
  },
};
